from __future__ import print_function, absolute_import
import os, tempfile, unittest, sys, re, warnings, io
from textwrap import dedent
from future.utils import bind_method, PY26, PY3, PY2, PY27
from future.moves.subprocess import check_output, STDOUT, CalledProcessError
if PY26:
    import unittest2 as unittest

def reformat_code(code):
    if code.startswith(b'\n'):
        code = code[1:]
    return dedent(code)


def order_future_lines(code):
    lines = code.split(b'\n')
    uufuture_line_numbers = [i for i, line in enumerate(lines) if line.startswith(b'from __future__ import ')]
    future_line_numbers = [i for i, line in enumerate(lines) if line.startswith(b'from future') or line.startswith(b'from past')]
    builtins_line_numbers = [i for i, line in enumerate(lines) if line.startswith(b'from builtins')]

    def mymax(numbers):
        if len(numbers) > 0:
            return max(numbers)
        return 0

    def mymin(numbers):
        if len(numbers) > 0:
            return min(numbers)
        return float(b'inf')

    uul = sorted([lines[i] for i in uufuture_line_numbers])
    sorted_uufuture_lines = dict(zip(uufuture_line_numbers, uul))
    fl = sorted([lines[i] for i in future_line_numbers])
    sorted_future_lines = dict(zip(future_line_numbers, fl))
    bl = sorted([lines[i] for i in builtins_line_numbers])
    sorted_builtins_lines = dict(zip(builtins_line_numbers, bl))
    new_lines = []
    for i in range(len(lines)):
        if i in uufuture_line_numbers:
            new_lines.append(sorted_uufuture_lines[i])
        elif i in future_line_numbers:
            new_lines.append(sorted_future_lines[i])
        elif i in builtins_line_numbers:
            new_lines.append(sorted_builtins_lines[i])
        else:
            new_lines.append(lines[i])

    return (b'\n').join(new_lines)


class VerboseCalledProcessError(CalledProcessError):

    def __init__(self, msg, returncode, cmd, output=None):
        self.msg = msg
        self.returncode = returncode
        self.cmd = cmd
        self.output = output
        return

    def __str__(self):
        return b"Command '%s' failed with exit status %d\nMessage: %s\nOutput: %s" % (
         self.cmd, self.returncode, self.msg, self.output)


class FuturizeError(VerboseCalledProcessError):
    pass


class PasteurizeError(VerboseCalledProcessError):
    pass


class CodeHandler(unittest.TestCase):

    def setUp(self):
        self.headers1 = reformat_code(b'\n        from __future__ import absolute_import\n        from __future__ import division\n        from __future__ import print_function\n        ')
        self.headers2 = reformat_code(b'\n        from __future__ import absolute_import\n        from __future__ import division\n        from __future__ import print_function\n        from __future__ import unicode_literals\n        from future import standard_library\n        standard_library.install_aliases()\n        from builtins import *\n        ')
        self.interpreters = [sys.executable]
        self.tempdir = tempfile.mkdtemp() + os.path.sep
        pypath = os.getenv(b'PYTHONPATH')
        if pypath:
            self.env = {b'PYTHONPATH': (os.getcwd() + os.pathsep + pypath)}
        else:
            self.env = {b'PYTHONPATH': (os.getcwd())}
        return

    def convert(self, code, stages=(1, 2), all_imports=False, from3=False, reformat=True, run=True, conservative=False):
        if reformat:
            code = reformat_code(code)
        self._write_test_script(code)
        self._futurize_test_script(stages=stages, all_imports=all_imports, from3=from3, conservative=conservative)
        output = self._read_test_script()
        if run:
            for interpreter in self.interpreters:
                _ = self._run_test_script(interpreter=interpreter)

        return output

    def compare(self, output, expected, ignore_imports=True):
        if ignore_imports:
            output = self.strip_future_imports(output)
            expected = self.strip_future_imports(expected)
        if isinstance(output, bytes) and not isinstance(expected, bytes):
            output = output.decode(b'utf-8')
        if isinstance(expected, bytes) and not isinstance(output, bytes):
            expected = expected.decode(b'utf-8')
        self.assertEqual(order_future_lines(output.rstrip()), expected.rstrip())
        return

    def strip_future_imports(self, code):
        output = []
        for line in code.split(b'\n'):
            if not (line.startswith(b'from __future__ import ') or line.startswith(b'from future ') or line.startswith(b'from builtins ') or b'install_hooks()' in line or b'install_aliases()' in line or line.startswith(b'from future.')):
                output.append(line)

        return (b'\n').join(output)

    def convert_check(self, before, expected, stages=(1, 2), all_imports=False, ignore_imports=True, from3=False, run=True, conservative=False):
        output = self.convert(before, stages=stages, all_imports=all_imports, from3=from3, run=run, conservative=conservative)
        if all_imports:
            headers = self.headers2 if 2 in stages else self.headers1
        else:
            headers = b''
        reformatted = reformat_code(expected)
        if headers in reformatted:
            headers = b''
        self.compare(output, headers + reformatted, ignore_imports=ignore_imports)
        return

    def unchanged(self, code, **kwargs):
        self.convert_check(code, code, **kwargs)
        return

    def _write_test_script(self, code, filename=b'mytestscript.py'):
        if isinstance(code, bytes):
            code = code.decode(b'utf-8')
        with io.open(self.tempdir + filename, b'wt', encoding=b'utf-8') as f:
            f.write(dedent(code))
        return

    def _read_test_script(self, filename=b'mytestscript.py'):
        with io.open(self.tempdir + filename, b'rt', encoding=b'utf-8') as f:
            newsource = f.read()
        return newsource

    def _futurize_test_script(self, filename=b'mytestscript.py', stages=(1, 2), all_imports=False, from3=False, conservative=False):
        params = []
        stages = list(stages)
        if all_imports:
            params.append(b'--all-imports')
        if from3:
            script = b'pasteurize.py'
        else:
            script = b'futurize.py'
            if stages == [1]:
                params.append(b'--stage1')
            elif stages == [2]:
                params.append(b'--stage2')
            if conservative:
                params.append(b'--conservative')
        fn = self.tempdir + filename
        call_args = [sys.executable, script] + params + [b'-w', fn]
        try:
            output = check_output(call_args, stderr=STDOUT, env=self.env)
        except CalledProcessError as e:
            with open(fn) as f:
                msg = b'Error running the command %s\n%s\nContents of file %s:\n\n%s' % (
                 (b' ').join(call_args),
                 b'env=%s' % self.env,
                 fn,
                 b'----\n%s\n----' % f.read())
            ErrorClass = FuturizeError if b'futurize' in script else PasteurizeError
            if not hasattr(e, b'output'):
                e.output = None
            raise ErrorClass(msg, e.returncode, e.cmd, output=e.output)

        return output

    def _run_test_script(self, filename=b'mytestscript.py', interpreter=sys.executable):
        fn = self.tempdir + filename
        try:
            output = check_output([interpreter, fn], env=self.env, stderr=STDOUT)
        except CalledProcessError as e:
            with open(fn) as f:
                msg = b'Error running the command %s\n%s\nContents of file %s:\n\n%s' % (
                 (b' ').join([interpreter, fn]),
                 b'env=%s' % self.env,
                 fn,
                 b'----\n%s\n----' % f.read())
            if not hasattr(e, b'output'):
                e.output = None
            raise VerboseCalledProcessError(msg, e.returncode, e.cmd, output=e.output)

        return output


skip26 = unittest.skipIf(PY26, b'this test is known to fail on Py2.6')

def expectedFailurePY3(func):
    if not PY3:
        return func
    return unittest.expectedFailure(func)


def expectedFailurePY26(func):
    if not PY26:
        return func
    return unittest.expectedFailure(func)


def expectedFailurePY27(func):
    if not PY27:
        return func
    return unittest.expectedFailure(func)


def expectedFailurePY2(func):
    if not PY2:
        return func
    return unittest.expectedFailure(func)


if not hasattr(unittest.TestCase, b'assertRaisesRegex'):
    unittest.TestCase.assertRaisesRegex = unittest.TestCase.assertRaisesRegexp

def assertRegex(self, text, expected_regex, msg=None):
    if isinstance(expected_regex, (str, unicode)):
        expected_regex = re.compile(expected_regex)
    if not expected_regex.search(text):
        msg = msg or b"Regex didn't match"
        msg = b'%s: %r not found in %r' % (msg, expected_regex.pattern, text)
        raise self.failureException(msg)
    return


if not hasattr(unittest.TestCase, b'assertRegex'):
    bind_method(unittest.TestCase, b'assertRegex', assertRegex)

class _AssertRaisesBaseContext(object):

    def __init__(self, expected, test_case, callable_obj=None, expected_regex=None):
        self.expected = expected
        self.test_case = test_case
        if callable_obj is not None:
            try:
                self.obj_name = callable_obj.__name__
            except AttributeError:
                self.obj_name = str(callable_obj)

        else:
            self.obj_name = None
        if isinstance(expected_regex, (bytes, str)):
            expected_regex = re.compile(expected_regex)
        self.expected_regex = expected_regex
        self.msg = None
        return

    def _raiseFailure(self, standardMsg):
        msg = self.test_case._formatMessage(self.msg, standardMsg)
        raise self.test_case.failureException(msg)
        return

    def handle(self, name, callable_obj, args, kwargs):
        if callable_obj is None:
            self.msg = kwargs.pop(b'msg', None)
            return self
        else:
            with self:
                callable_obj(*args, **kwargs)
            return


class _AssertWarnsContext(_AssertRaisesBaseContext):

    def __enter__(self):
        for v in sys.modules.values():
            if getattr(v, b'__warningregistry__', None):
                v.__warningregistry__ = {}

        self.warnings_manager = warnings.catch_warnings(record=True)
        self.warnings = self.warnings_manager.__enter__()
        warnings.simplefilter(b'always', self.expected)
        return self

    def __exit__(self, exc_type, exc_value, tb):
        self.warnings_manager.__exit__(exc_type, exc_value, tb)
        if exc_type is not None:
            return
        else:
            try:
                exc_name = self.expected.__name__
            except AttributeError:
                exc_name = str(self.expected)

            first_matching = None
            for m in self.warnings:
                w = m.message
                if not isinstance(w, self.expected):
                    continue
                if first_matching is None:
                    first_matching = w
                if self.expected_regex is not None and not self.expected_regex.search(str(w)):
                    continue
                self.warning = w
                self.filename = m.filename
                self.lineno = m.lineno
                return

            if first_matching is not None:
                self._raiseFailure((b'"{}" does not match "{}"').format(self.expected_regex.pattern, str(first_matching)))
            if self.obj_name:
                self._raiseFailure((b'{} not triggered by {}').format(exc_name, self.obj_name))
            else:
                self._raiseFailure((b'{} not triggered').format(exc_name))
            return


def assertWarns(self, expected_warning, callable_obj=None, *args, **kwargs):
    context = _AssertWarnsContext(expected_warning, self, callable_obj)
    return context.handle(b'assertWarns', callable_obj, args, kwargs)


if not hasattr(unittest.TestCase, b'assertWarns'):
    bind_method(unittest.TestCase, b'assertWarns', assertWarns)
